export type Logger = {
    info: (...data: any[]) => void
    warn: (...data: any[]) => void
    error: (...data: any[]) => void
    debug: (...data: any[]) => void
}

// TODO: This is not needed, get rid of it
export function createConsoleLogger(): Logger {
    return console
}

export function createSilentLogger(): Logger {
    return {
        info: () => {},
        warn: () => {},
        error: () => {},
        debug: () => {},
    }
}
